    array (
      0 => '交界性逸搏心律是窦房结发放冲动过慢或冲动不能传出时，房室交界区作为后备起搏点被动发放冲动，形成频率约 40–60 次/分的规则节律。冲动经希氏束-浦肯野系统下传，故 QRS 通常窄；心房可无 P 波，或由逆行传导产生在 II、III、aVF 倒置、aVR 直立的 P 波。',
      1 => '室性逸搏心律是窦房结与房室交界区均不能及时发放或下传冲动时，心室起搏点被动发放冲动，形成频率约 20–40 次/分的宽 QRS 节律。冲动在心室肌细胞间缓慢传导，QRS ≥0.12 s，ST-T 方向与 QRS 主波相反；常提示严重传导系统疾病、代谢紊乱或临终状态。',
      2 => '窦房结主导：P 波在 I、II、aVF 直立，每个 P 后跟随 QRS，频率 60–100 次/分。',
      3 => '加速性室性自主心律是心室异位起搏点以高于其固有频率、但低于室速频率发放冲动，形成频率约 50–110 次/分、QRS ≥0.12 s 的节律。它常与窦性心律竞争，出现等频房室分离、室性融合波或夺获波，多见于急性心肌梗死再灌注后，也可由洋地黄中毒、心肌炎和电解质紊乱引起。',
    ),
