    'explanation' => '《室性逸搏心律》的定义：室性逸搏心律是窦房结与房室交界区均不能及时发放或下传冲动时，心室起搏点被动发放冲动，形成频率约 20–40 次/分的宽 QRS 节律。冲动在心室肌细胞间缓慢传导，QRS ≥0.12 s，ST-T 方向与 QRS 主波相反；常提示严重传导系统疾病、代谢紊乱或临终状态。',
