      1 => '室性逸搏心律是窦房结与房室交界区均不能及时发放或下传冲动时，心室起搏点被动发放冲动，形成频率约 20–40 次/分的宽 QRS 节律。冲动在心室肌细胞间缓慢传导，QRS ≥0.12 s，ST-T 方向与 QRS 主波相反；常提示严重传导系统疾病、代谢紊乱或临终状态。',
      2 => '交界性逸搏心律是窦房结发放冲动过慢或冲动不能传出时，房室交界区作为后备起搏点被动发放冲动，形成频率约 40–60 次/分的规则节律。冲动经希氏束-浦肯野系统下传，故 QRS 通常窄；心房可无 P 波，或由逆行传导产生在 II、III、aVF 倒置、aVR 直立的 P 波。',
