  270 => 
  array (
    'id' => 'sec-block-002',
    'chapter' => 'block',
    'sourceId' => 'av-block-1',
    'stem' => '关于《一度房室传导阻滞》，以下哪项是最具特异性的线索？',
    'options' => 
    array (
      0 => 'PR 逐搏延长后出现 QRS 脱漏，脱漏后 PR 缩短，呈周期性“渐长—脱漏—重置”，是文氏现象最特异的线索；脱漏前最后一个 PR 通常最长。',
      1 => 'PR 间期恒定 >0.20 s，且每个 P 波后均有 QRS，是一度房室阻滞最直接的诊断线索；若同时 QRS 增宽，需考虑合并束支阻滞或病变更靠远端。',
      2 => 'PR 间期恒定而 QRS 突然、周期性脱漏，且脱漏前无 PR 延长，是二度 II 型最特异的线索；若 QRS 增宽，更支持希氏束下阻滞。',
      3 => 'P 波与 QRS 完全无关、心房率高于心室率、PR 间期逐搏变化，是三度房室阻滞最特异的线索；QRS 宽度与逸搏频率可提示阻滞部位。',
    ),
    'answerIndex' => 1,
    'explanation' => '《一度房室传导阻滞》的最具特异性的线索：PR 间期恒定 >0.20 s，且每个 P 波后均有 QRS，是一度房室阻滞最直接的诊断线索；若同时 QRS 增宽，需考虑合并束支阻滞或病变更靠远端。',
    'difficulty' => 1,
  ),
  271 => 
  array (
    'id' => 'sec-block-003',
    'chapter' => 'block',
    'sourceId' => 'av-block-1',
    'stem' => '关于《一度房室传导阻滞》，以下哪项是定义？',
    'options' => 
    array (
      0 => '三度房室传导阻滞是心房冲动完全不能下传心室，心房与心室由各自起搏点独立控制，形成完全性房室分离。窦性 P 波按自身频率出现，心室由交界性或室性逸搏维持，频率通常 20–40 次/分（室性）或 40–60 次/分（交界性）。',
      1 => '一度房室传导阻滞是房室传导延迟，使 PR 间期恒定超过 0.20 s，但每个心房冲动仍能下传心室，没有 QRS 脱漏。它反映房室传导时间延长而非传导中断，可见于迷走张力增高、药物、缺血、心肌炎或传导系统退行性变。',
      2 => '二度 I 型房室传导阻滞是房室结传导逐渐延迟，PR 间期逐搏延长，直至一个心房冲动不能下传、QRS 脱漏，随后 PR 缩短并开始新的周期。脱漏使心室率低于心房率，典型者呈 4:3 或 3:2 传导，QRS 多窄，多属房室结内阻滞，常与迷走张力增高或药物有关。',
      3 => '二度 II 型房室传导阻滞是在固定 PR 间期下突然发生 QRS 脱漏，脱漏前没有 PR 进行性延长。阻滞部位多在希氏束或双侧束支水平，常伴 QRS 增宽，进展为完全性房室阻滞的风险较高。它与二度 I 型的本质区别在于阻滞位于房室结以下，而非房室结内的渐进性疲劳。',
    ),
    'answerIndex' => 1,
    'explanation' => '《一度房室传导阻滞》的定义：一度房室传导阻滞是房室传导延迟，使 PR 间期恒定超过 0.20 s，但每个心房冲动仍能下传心室，没有 QRS 脱漏。它反映房室传导时间延长而非传导中断，可见于迷走张力增高、药物、缺血、心肌炎或传导系统退行性变。',
    'difficulty' => 1,
  ),
  272 => 
  array (
    'id' => 'sec-block-004',
