    'sourceId' => 'av-block-1',
    'stem' => '关于《一度房室传导阻滞》的诊断标准，以下哪项正确？',
    'options' => 
    array (
      0 => '成人 PR 间期 >0.20 s，每个 P 波后均有 QRS。',
