      2 => 'P 波为窦性；QRS 多窄，若增宽提示合并束支阻滞或阻滞位于希氏束下。',
      3 => 'PR 间期恒定，无进行性延长，也无 QRS 脱漏。',
    ),
    'answerIndex' => 0,
    'explanation' => '《一度房室传导阻滞》诊断标准：成人 PR 间期 >0.20 s，每个 P 波后均有 QRS。',
    'difficulty' => 1,
  ),
  273 => 
  array (
    'id' => 'sec-block-005',
    'chapter' => 'block',
    'sourceId' => 'av-block-1',
    'stem' => '关于《一度房室传导阻滞》的判读步骤，以下哪项正确？',
    'options' => 
    array (
      0 => '观察 QRS 宽度与形态，宽 QRS 提示更远端病变或合并束支阻滞。',
      1 => '逐搏测量 PR，确认恒定且没有 QRS 脱漏。',
      2 => '在 II 导联选择 P 波起点清晰的搏动，测量 P 起点到 QRS 起点。',
      3 => '结合药物、电解质、缺血和症状，寻找可逆原因。',
    ),
    'answerIndex' => 2,
    'explanation' => '《一度房室传导阻滞》判读步骤：在 II 导联选择 P 波起点清晰的搏动，测量 P 起点到 QRS 起点。',
    'difficulty' => 1,
  ),
  274 => 
  array (
    'id' => 'sec-block-006',
