    'sourceId' => 'av-block-1',
    'stem' => '关于《一度房室传导阻滞》的危险信号，以下哪项正确？',
    'options' => 
    array (
      0 => '急性下壁心肌梗死、心肌炎或洋地黄中毒背景。',
