    'difficulty' => 1,
  ),
  275 => 
  array (
    'id' => 'sec-block-007',
    'chapter' => 'block',
    'sourceId' => 'av-block-1',
    'stem' => '关于《一度房室传导阻滞》的处理原则，以下哪项正确？',
    'options' => 
    array (
      0 => '症状性心动过缓：阿托品 1 mg 静脉推注，每 3–5 分钟重复，最大 3 mg；无效时经皮起搏或肾上腺素 2–10 μg/min。',
      1 => '无症状且无进展者：停用或调整减慢房室传导的药物，纠正电解质，定期随访。',
      2 => '伴晕厥、进行性传导阻滞或三度阻滞风险者准备起搏，避免用单纯阿托品替代。',
      3 => '有症状或 PR 明显延长：评估病因；迷走张力高者运动后 PR 可缩短。',
    ),
    'answerIndex' => 1,
    'explanation' => '《一度房室传导阻滞》处理原则：无症状且无进展者：停用或调整减慢房室传导的药物，纠正电解质，定期随访。',
    'difficulty' => 1,
  ),
  276 => 
  array (
