    'options' => 
    array (
      0 => '阻滞也可位于心房、希氏束或束支；希氏束内或希氏束下阻滞常伴 QRS 增宽，进展风险更高。',
      1 => '房室结传导延迟是最常见机制，迷走张力增高、药物和缺血使房室结细胞除极与传导速度下降，PR 延长。',
