    'stem' => '关于《二度 II 型房室传导阻滞》，以下哪项是一句话描述？',
    'options' => 
    array (
      0 => 'PR 恒定，QRS 却周期性脱漏；病变多在希氏束以下，易进展为三度，起搏评估要更积极。',
      1 => '每个 P 波都下传，但 PR 恒定 >0.20 s；多数无症状，重点找病因并监测是否进展。',
