    'sourceId' => 'ischemia-st',
    'stem' => '关于《心肌缺血与 ST 段压低》，以下哪项是最具特异性的线索？',
    'options' => 
    array (
      0 => 'II、III、aVF 中至少两个相邻导联 ST 抬高 ≥1 mm，伴 aVL（最敏感）镜像性压低；III 导联抬高幅度大于 II 导联提示右冠状动脉闭塞。疑右室梗死时加做 V4R，ST 抬高 ≥1 mm 即有诊断价值。',
