  345 => 
  array (
    'id' => 'sec-ischemia-027',
    'chapter' => 'ischemia',
    'sourceId' => 'ischemia-st',
    'stem' => '关于《心肌缺血与 ST 段压低》，以下哪项是定义？',
    'options' => 
    array (
      0 => '急性前壁 ST 段抬高型心肌梗死是左前降支急性闭塞导致前壁与前间隔心肌透壁性缺血坏死，心电图上相邻胸前导联（V1–V4）出现 ST 段抬高，常伴下壁导联镜像性 ST 压低。它属于需要立即开通血管的急症，诊断与再灌注决策不能等待心肌损伤标志物。',
      1 => '心肌缺血与 ST 段压低指冠状动脉供血不足导致心内膜下心肌缺血，心电图上出现水平型或下斜型 ST 段压低与 T 波倒置，可伴或不伴心肌肌钙蛋白升高。肌钙蛋白升高者为 NSTEMI，肌钙蛋白正常者为不稳定型心绞痛，两者统称非 ST 段抬高型急性冠脉综合征。',
      2 => '急性心包炎是心包脏层与壁层的急性炎症，常由病毒、结核、自身免疫病、尿毒症或肿瘤引起。炎症累及心外膜下心肌，产生弥漫性损伤电流，心电图上表现为多导联凹面 ST 抬高与 PR 段压低，临床常伴胸痛与心包摩擦音。',
      3 => '急性下壁 ST 段抬高型心肌梗死多由右冠状动脉或回旋支急性闭塞引起，心电图上 II、III、aVF 相邻导联 ST 段抬高，常在 I、aVL 出现镜像性压低，可合并右室梗死与房室阻滞。下壁心梗的早期风险与右室受累、低血压和缓慢性心律失常密切相关。',
    ),
    'answerIndex' => 1,
    'explanation' => '《心肌缺血与 ST 段压低》的定义：心肌缺血与 ST 段压低指冠状动脉供血不足导致心内膜下心肌缺血，心电图上出现水平型或下斜型 ST 段压低与 T 波倒置，可伴或不伴心肌肌钙蛋白升高。肌钙蛋白升高者为 NSTEMI，肌钙蛋白正常者为不稳定型心绞痛，两者统称非 ST 段抬高型急性冠脉综合征。',
    'difficulty' => 3,
  ),
